    { ko: "(친구에게) 요즘 돈이 좀 빠듯해서, 다음에 해도 될까?", en: "Money's tight right now. Can I take a rain check?" },
    { ko: "(친구에게) 오늘 밤 파티는 다음에 가도 될까?", en: "Can I take a rain check on the party tonight?" }
