    { ko: "(친구에게) 오늘 밤 영화랑 볼링 중에 고민 중이야.", en: "I'm torn between a movie and bowling tonight." },
    { ko: "(바리스타에게) 라떼랑 모카 중에 못 고르겠어요.", en: "I'm torn between a latte and a mocha." },
    { ko: "(가이드에게) 저희 박물관이랑 동물원 중에 고민 중이에요.", en: "We're torn between the museum and the zoo." },
    { ko: "(동료에게) 시애틀 자리랑 오스틴 자리 중에 고민 중이야.", en: "I'm torn between the Seattle job and the Austin job." },
    { ko: "(친구에게) 엄마 선물로 스카프랑 지갑 중에 고민이야.", en: "I'm torn between a scarf and a wallet for my mom." },
    { ko: "(웨이터에게) 저희 치즈케이크랑 브라우니 중에 못 고르겠어요.", en: "We're torn between the cheesecake and the brownie." },
    { ko: "(렌터카 직원에게) 소형차랑 SUV 중에 고민 중이에요.", en: "I'm torn between a compact and an SUV." }
